                if (ix && iy) {
                    if (x.a != y.a) return Long.compare(x.a, y.a);
                    return Long.compare(x.b, y.b);
                }
                return ix ? -1 : 1;
            }

            long lhs = x.b * (y.a - 1);
            long rhs = y.b * (x.a - 1);

            if (lhs != rhs) return lhs > rhs ? -1 : 1;
            if (x.a != y.a) return Long.compare(x.a, y.a);
            return Long.compare(x.b, y.b);
        }
